#include <cstring>
#include <type_traits>

void FieldBase::AddRawValue(const FIT_FLOAT64 rawValue, const FIT_UINT8 fieldArrayIndex)
{
    FIT_FLOAT64 roundedValue = FieldBase::Round(rawValue);
    switch (GetType())
    {
        case FIT_BASE_TYPE_BYTE:
        case FIT_BASE_TYPE_ENUM:
        case FIT_BASE_TYPE_SINT8:
        case FIT_BASE_TYPE_UINT8:
        case FIT_BASE_TYPE_UINT8Z:
            SetUINT8Value(static_cast<FIT_UINT8>(roundedValue), fieldArrayIndex);
            break;

        case FIT_BASE_TYPE_SINT16:
        case FIT_BASE_TYPE_UINT16:
        case FIT_BASE_TYPE_UINT16Z:
            SetUINT16Value(static_cast<FIT_UINT16>(roundedValue), fieldArrayIndex);
            break;

        case FIT_BASE_TYPE_SINT32:
        case FIT_BASE_TYPE_UINT32:
        case FIT_BASE_TYPE_UINT32Z:
            SetUINT32Value(static_cast<FIT_UINT32>(roundedValue), fieldArrayIndex);
            break;

        case FIT_BASE_TYPE_FLOAT32:
        {
            FIT_FLOAT32 float32Value = static_cast<FIT_FLOAT32>(roundedValue);
            FIT_UINT32 uint32Value;
            static_assert(sizeof(float32Value) == sizeof(uint32Value), "Sizes must match");
            std::memcpy(&uint32Value, &float32Value, sizeof(uint32Value));
            SetUINT32Value(uint32Value, fieldArrayIndex);
            break;
        }

        case FIT_BASE_TYPE_FLOAT64:
        {
            size_t requiredSize = (fieldArrayIndex + 1) * sizeof(FIT_FLOAT64);
            if (values.size() < requiredSize)
            {
                values.resize(requiredSize);
            }
            static_assert(sizeof(rawValue) == sizeof(FIT_FLOAT64), "FIT_FLOAT64 must be 8 bytes");
            std::memcpy(&values[fieldArrayIndex * sizeof(FIT_FLOAT64)], &rawValue, sizeof(rawValue));
            break;
        }

        case FIT_BASE_TYPE_SINT64:
            SetSINT64Value(static_cast<FIT_SINT64>(rawValue), fieldArrayIndex);
            break;

        case FIT_BASE_TYPE_UINT64:
        case FIT_BASE_TYPE_UINT64Z:
            SetUINT64Value(static_cast<FIT_UINT64>(rawValue), fieldArrayIndex);
            break;

        default:
            break;
    }
}
